'use strict';
const app=document.querySelector('#app'),KEY='kingmick-data-v1',weights=[20,15,10,5];
let store=read(),draft=null,current=null,screen='home',tab=0,betRace=0;
function read(){try{let d=JSON.parse(localStorage.getItem(KEY))||{meetings:[]};d.meetings ||= [];d.profiles ||= [];return d}catch{return {meetings:[],profiles:[]}}}
function persist(){localStorage.setItem(KEY,JSON.stringify(store))}
function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function button(s,action,cls=''){return `<button class="btn ${cls}" data-a="${action}">${s}</button>`}
function field(name,id,val='',type='text',attrs=''){return `<div class="field"><label for="${id}">${name}</label><input id="${id}" type="${type}" value="${escapeHTML(val)}" ${attrs}></div>`}
function title(k,t,sub=''){return `<div class="eyebrow">${escapeHTML(k)}</div><h1>${escapeHTML(t)}</h1>${sub?`<p class="muted">${escapeHTML(sub)}</p>`:''}`}
function show(html){app.innerHTML=html;window.scrollTo(0,0)}
function home(){screen='home';show(title('KINGMICK V4.3','Welcome back')+`<div class="stack">${button('QUADDIE','quaddie')}${button('SINGLE RACE','single')}${button('HISTORY','history','secondary')}${button('KINGMICK PERFORMANCE','stats','secondary')}${button('TIPSTERS','profiles','secondary')}</div><div class="panel compact muted">All entries stay in this browser on this device. Use Backup in History to protect your data.</div>`)}
function quaddie(){screen='quaddie';show(title('QUADDIE','Quaddie')+`<div class="stack">${button('NEW QUADDIE','newq')}${button('CONTINUE QUADDIE','continue','secondary')}</div>`)}
function blankTip(mode){return {name:'',profileId:null,legs:Array.from({length:mode==='single'?1:4},()=>['','','',''])}}
function newMeeting(mode){tab=0;betRace=0;draft={id:crypto.randomUUID?.()||String(Date.now()),mode,name:'',date:new Date().toLocaleDateString('en-CA'),race:1,count:8,tipsters:[],index:0,created:Date.now(),completed:false};store.meetings.unshift(draft);persist();setup()}
function baseSetup(){screen='setup';show(title('MEETING SETUP',draft.mode==='single'?'New Single Race':'New Quaddie')+`<div class="panel">${field('Track / Meeting Name','meeting',draft.name)}${field('Date','date',draft.date,'date')}${draft.mode==='single'?field('Race Number','race',draft.race,'number','min="1"'):''}${field('Number of Tipsters','count',draft.count,'number','min="2" max="100"')}</div>${button('CONTINUE TO TIPSTER ENTRY','begin')}${button('BACK','home','ghost')}`)}
function baseSetupSave(){const name=document.querySelector('#meeting').value.trim(),date=document.querySelector('#date').value,count=Number(document.querySelector('#count').value),race=draft.mode==='single'?Number(document.querySelector('#race').value):1;if(!name||!date||!Number.isInteger(count)||count<2||count>100||!Number.isInteger(race)||race<1)return alert('Enter a meeting name, date, valid tipster count (2–100) and race number.');draft.name=name;draft.date=date;draft.count=count;draft.race=race;while(draft.tipsters.length<count)draft.tipsters.push(blankTip(draft.mode));draft.tipsters.length=count;persist();entry()}
function entry(){screen='entry';let t=draft.tipsters[draft.index],legs=t.legs.length;let h=title('TIPSTER ENTRY',`Tipster ${draft.index+1} of ${draft.count}`,`${draft.name} • Four ordered picks per ${legs===1?'race':'leg'}`)+`<div class="panel">${field('Tipster Name','tipname',t.name,'text','list="knownTipsters" autocomplete="off"')}<datalist id="knownTipsters">${store.profiles.map(p=>`<option value="${escapeHTML(p.name)}"></option>`).join('')}</datalist><p class="muted compact">Select an existing tipster suggestion to link their history. Similar names will be checked before saving.</p>`;for(let l=0;l<legs;l++){h+=`<h3>${legs===1?'Race '+draft.race:'Leg '+(l+1)}</h3><div class="picks">`;for(let p=0;p<4;p++)h+=`<div class="field"><label>${['1st','2nd','3rd','4th'][p]} pick</label><input class="pick" data-l="${l}" data-p="${p}" inputmode="numeric" pattern="[0-9]*" value="${escapeHTML(t.legs[l][p])}" placeholder="No."></div>`;h+='</div>'}h+=`</div><div class="actions">${draft.index>0?button('PREVIOUS','prev','secondary'):''}${button(draft.index===draft.count-1?'SAVE & REVIEW':'SAVE & NEXT','next')}</div><p class="muted compact">Scoring: 20 / 15 / 10 / 5. Changes save locally as you enter them.</p>`;show(h)}
function capture(){let t=draft.tipsters[draft.index];t.name=document.querySelector('#tipname').value.trim();document.querySelectorAll('.pick').forEach(x=>t.legs[+x.dataset.l][+x.dataset.p]=x.value.trim());persist()}
function validateTip(t){if(!t.name)return 'Enter the tipster name.';for(let l=0;l<t.legs.length;l++){let picks=t.legs[l];for(let p=0;p<4;p++)if(!/^\d+$/.test(picks[p])||Number(picks[p])<1)return `Missing or invalid selection: ${t.legs.length===1?'Race':`Leg ${l+1}`}, pick ${p+1}.`;if(new Set(picks.map(Number)).size!==4)return `${t.legs.length===1?'Race':`Leg ${l+1}`}: a horse cannot be selected twice by the same tipster.`}return null}
function review(){screen='review';let problems=draft.tipsters.map((t,i)=>validateTip(t)?`Tipster ${i+1}: ${validateTip(t)}`:null).filter(Boolean),valid=!problems.length&&draft.tipsters.length>=2;let n=draft.mode==='single'?1:4;let duplicates=duplicateTipsters(draft);if(duplicates.length){problems.push('Duplicate tipster: '+duplicates.join(', '));valid=false}show(title('MEETING REVIEW',draft.name,`${draft.date} • ${draft.count} tipsters`)+`<div class="panel"><div class="row"><span>Selections</span><strong>${draft.tipsters.filter(t=>!validateTip(t)).length*n*4}/${draft.count*n*4}</strong></div><div class="row"><span>Expected points per leg/race</span><strong>${draft.count*50}</strong></div><div class="row"><span>Validation</span><strong class="${valid?'good':'bad'}">${valid?'PASSED':'NEEDS ATTENTION'}</strong></div></div>${problems.length?`<div class="notice">${problems.map(escapeHTML).join('<br>')}</div>`:''}<div class="panel"><h3>Tipsters</h3>${draft.tipsters.map((t,i)=>`<div class="row"><span>${escapeHTML(t.name||'Tipster '+(i+1))}</span><button class="mini" data-edit="${i}">Edit</button></div>`).join('')}</div><button class="btn" data-a="generate" ${valid?'':'disabled'}>GENERATE BETTING RECOMMENDATIONS</button>${button('BACK TO ENTRY','entry','ghost')}`)}
function board(m,leg){if(m.completed&&m.snapshot?.boards?.[leg])return structuredClone(m.snapshot.boards[leg]);let map=new Map;for(const t of m.tipsters){for(let p=0;p<4;p++){let horse=String(Number(t.legs[leg][p]));let row=map.get(horse)||{horse,points:0,counts:[0,0,0,0]};row.points+=weights[p];row.counts[p]++;map.set(horse,row)}}let rows=[...map.values()].sort((a,b)=>b.points-a.points||b.counts[0]-a.counts[0]||b.counts[1]-a.counts[1]||b.counts[2]-a.counts[2]||b.counts[3]-a.counts[3]||Number(a.horse)-Number(b.horse));let last,rank=0;rows.forEach((r,i)=>{if(r.points!==last)rank=i+1;r.rank=rank;last=r.points;r.tied=rows.filter(x=>x.points===r.points).length>1});return rows}
function audits(m){return Array.from({length:m.mode==='single'?1:4},(_,i)=>board(m,i).reduce((a,r)=>a+r.points,0)===m.count*50)}
function generate(){if(draft.tipsters.length<2)return alert('At least two finalised tipsters are required.');if(draft.tipsters.some(t=>validateTip(t)))return review();for(const t of draft.tipsters)if(!assignProfile(t,draft))return;if(duplicateTipsters(draft).length)return alert('Duplicate tipster profiles detected.');if(!audits(draft).every(Boolean))return alert('Point-total audit failed.');draft.completed=true;draft.snapshot=makeSnapshot(draft);draft.finalizedAt=Date.now();persist();current=draft;draft=null;recommend()}
function leader(){screen='leader';let m=current,rows=board(m,tab),total=rows.reduce((a,r)=>a+r.points,0),cut=selectionFor(m,tab).at(-1)?.points;show(title('FULL LEADERBOARDS',m.name,`Points verified: ${total}/${m.count*50}`)+`<div class="tabs">${Array.from({length:m.mode==='single'?1:4},(_,i)=>`<button data-tab="${i}" class="${tab===i?'active':''}">${m.mode==='single'?'Race':'Leg '+(i+1)}</button>`).join('')}</div><div class="panel scroll"><table><thead><tr><th>Rank</th><th>Horse</th><th>Pts</th><th>1st</th><th>2nd</th><th>3rd</th><th>4th</th><th>Selected</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.rank}${r.tied?' =':''}</td><td>${escapeHTML(r.horse)}</td><td>${r.points}</td>${r.counts.map(c=>`<td>${c}</td>`).join('')}<td>${selectionFor(m,tab).some(x=>x.horse===r.horse)?'✓':''}</td></tr>`).join('')}</tbody></table></div>${rows.some(r=>r.tied)?`<div class="notice">Points ties: ${[...new Set(rows.filter(r=>r.tied).map(r=>r.points))].map(p=>`${p} pts (${rows.filter(r=>r.points===p).map(r=>r.horse).join(' / ')})`).join('; ')}. ${rows.some(r=>r.points===cut&&r.tied)?'Tie at selection cutoff included.':''}</div>`:''}${button('BACK','recommend','ghost')}`)}
function rankOptions(){return current.mode==='single'?[current.race]:[1,2,3,4]}
function chooseRace(){return `<div class="field"><label>Race / Quaddie Leg</label><select id="racechoice">${rankOptions().map((r,i)=>`<option value="${i}" ${i===betRace?'selected':''}>${current.mode==='single'?'Race '+r:'Leg '+r}</option>`).join('')}</select></div>`}
function permutations(rows,allowed,positions){let out=[];function recur(pos,used,ticket){if(pos>positions){out.push(ticket);return}rows.forEach((r,i)=>{if(!used.has(i)&&allowed[i]?.includes(pos)){let next=new Set(used);next.add(i);recur(pos+1,next,[...ticket,r.horse])}})}recur(1,new Set,[]);return out}
function daily(){screen='daily';show(title('DAILY DOUBLE',current.name)+`<div class="panel"><p>Choose consecutive Quaddie legs:</p><select id="pair"><option value="0">Legs 1 & 2</option><option value="1">Legs 2 & 3</option><option value="2">Legs 3 & 4</option></select></div>${button('SHOW DAILY DOUBLE','showdaily')}${button('BACK','recommend','ghost')}`)}
function showdaily(){let i=Number(document.querySelector('#pair').value),a=selectionFor(current,i),b=selectionFor(current,i+1);show(title('DAILY DOUBLE',`Legs ${i+1} & ${i+2}`)+`<div class="panel"><div class="row"><span>Leg ${i+1}</span><strong>${a.map(x=>x.horse).join(', ')}</strong></div><div class="row"><span>Leg ${i+2}</span><strong>${b.map(x=>x.horse).join(', ')}</strong></div><p>${a.length*b.length} combinations</p></div>${button('BACK','daily','ghost')}`)}
function treble(){screen='treble';show(title('TREBLE',current.name)+`<div class="panel"><label>Three consecutive legs</label><select id="triple"><option value="0">Legs 1, 2 & 3</option><option value="1">Legs 2, 3 & 4</option></select></div>${button('SHOW TREBLE','showtreble')}${button('BACK','recommend','ghost')}`)}
function showtreble(){let i=Number(document.querySelector('#triple').value),legs=[i,i+1,i+2],s=legs.map(l=>selectionFor(current,l));show(title('TREBLE',`Legs ${legs.map(x=>x+1).join(', ')}`)+`<div class="panel">${s.map((a,j)=>`<div class="row"><span>Leg ${legs[j]+1}</span><strong>${a.map(x=>x.horse).join(', ')}</strong></div>`).join('')}<p>${s.reduce((n,a)=>n*a.length,1)} combinations</p></div>${button('BACK','treble','ghost')}`)}
function history(){screen='history';show(title('HISTORY','Saved Meetings')+`<div class="stack">${store.meetings.map(m=>`<div class="panel"><div class="row"><strong>${escapeHTML(m.name||'Unfinished meeting')}</strong><span class="badge">${m.mode==='single'?'Single Race':'Quaddie'}</span></div><p class="muted compact">${escapeHTML(m.date)} • ${m.tipsters.filter(t=>!validateTip(t)).length}/${m.count} tipsters • ${m.completed?'Completed':'In progress'}</p><div class="actions"><button class="btn secondary" data-open="${escapeHTML(m.id)}">${m.completed?'VIEW':'CONTINUE'}</button><button class="btn ghost" data-delete="${escapeHTML(m.id)}">DELETE</button></div></div>`).join('')||'<div class="panel muted">No saved meetings yet.</div>'}</div><div class="panel"><h3>Backup / Restore</h3>${button('EXPORT BACKUP','export','secondary')}<div class="field"><label>Restore a KingMick JSON backup</label><input type="file" id="restore" accept="application/json,.json"></div><p class="muted compact">Restoring replaces the current on-device meeting history. Keep backups somewhere safe.</p></div>${button('HOME','home','ghost')}`)}
function v42Stats(){screen='stats';let ms=store.meetings.filter(m=>m.completed);show(title('KINGMICK PERFORMANCE','Strategy Showdown')+`<div class="panel"><div class="row"><span>Completed meetings</span><strong>${ms.length}</strong></div><div class="row"><span>Quaddies</span><strong>${ms.filter(m=>m.mode==='quaddie').length}</strong></div><div class="row"><span>Single races</span><strong>${ms.filter(m=>m.mode==='single').length}</strong></div><div class="row"><span>Tipster entries</span><strong>${ms.reduce((n,m)=>n+m.tipsters.length,0)}</strong></div></div>${performanceSummary()}${button('HOME','home','ghost')}`)}
function exportData(){let blob=new Blob([JSON.stringify({version:4,meetings:store.meetings,profiles:store.profiles},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kingmick-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function restoreData(file){if(!file)return;file.text().then(t=>{let data=JSON.parse(t);if(!Array.isArray(data.meetings))throw Error('Invalid backup');if(!confirm('Replace all current KingMick meetings with this backup?'))return;store={meetings:data.meetings,profiles:Array.isArray(data.profiles)?data.profiles:[]};migrate();persist();history()}).catch(()=>alert('Could not read a valid KingMick backup.'))}
function openMeeting(id){let m=store.meetings.find(x=>x.id===id);if(!m)return;current=m;tab=0;betRace=0;strategyMode='';strategyKey='';if(m.completed){meetingDetails()}else{draft=m;if(!m.name)setup();else entry()}}
function baseDispatch(a){if(a.startsWith('perf:')){performanceFilter=a.slice(5);stats()}else if(a.startsWith('mode:')){strategyMode=a.slice(5);strategyKey='';bets(screen)}else if(a.startsWith('option:')){strategyKey=a.slice(7);bets(screen)}else if(a==='copybet')copyBet();else if(a==='home')home();else if(a==='quaddie')quaddie();else if(a==='newq')newMeeting('quaddie');else if(a==='single')newMeeting('single');else if(a==='begin')setupSave();else if(a==='next')advance(1);else if(a==='prev')advance(-1);else if(a==='entry')entry();else if(a==='generate')generate();else if(a==='recommend')recommend();else if(a==='leader')leader();else if(a==='quaddiebet')quaddiebet();else if(a==='multis')multis();else if(a==='daily')daily();else if(a==='showdaily')showdaily();else if(a==='treble')treble();else if(a==='showtreble')showtreble();else if(['exacta','trifecta','firstfour'].includes(a)){strategyMode='';strategyKey='';bets(a)}else if(a==='history')history();else if(a==='stats')stats();else if(a==='profiles')profilesPage();else if(a==='meetingdetails')meetingDetails();else if(a==='originaltips')originalTips();else if(a==='results')resultsPage();else if(a==='saveresults')saveResults();else if(a==='performance')meetingPerformance();else if(a==='continue')history();else if(a==='export')exportData();else if(a==='copyq'){let m=current,t=[0,1,2,3].map(i=>selectionFor(m,i));copyText(`KingMick — ${m.name} (${m.date})\n${t.map((x,i)=>`Leg ${i+1}: ${x.map(r=>r.horse+' ('+r.points+' pts)').join(', ')}`).join('\n')}\n${t.reduce((n,x)=>n*x.length,1)} combinations`)} }
document.querySelector('#home').addEventListener('click',home);
app.addEventListener('click',e=>{let a=e.target.closest('[data-a]');if(a){dispatch(a.dataset.a);return}let edit=e.target.closest('[data-edit]');if(edit){draft.index=Number(edit.dataset.edit);entry();return}let t=e.target.closest('[data-tab]');if(t){tab=Number(t.dataset.tab);leader();return}let o=e.target.closest('[data-open]');if(o){openMeeting(o.dataset.open);return}let d=e.target.closest('[data-delete]');if(d&&confirm('Permanently delete this meeting?')){store.meetings=store.meetings.filter(m=>m.id!==d.dataset.delete);persist();history()}});
app.addEventListener('change',e=>{if(e.target.id==='profilefilter')profilesPage();if(e.target.id==='racechoice'){betRace=Number(e.target.value);bets(screen)}if(e.target.id==='restore')restoreData(e.target.files[0]);if(e.target.classList.contains('pick')||e.target.id==='tipname')capture()});
app.addEventListener('input',e=>{if(screen==='entry'&&(e.target.classList.contains('pick')||e.target.id==='tipname'))capture()});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js?v=4.3',{updateViaCache:'none'}).catch(()=>{}));


// KingMick v2: immutable prediction snapshots, results, linked tipster profiles.
function normName(n){return String(n||'').normalize('NFKC').toLowerCase().trim().replace(/\s+/g,' ').replace(/[^a-z0-9 ]/g,'')}
function newId(){return crypto.randomUUID?.()||String(Date.now())+'-'+Math.random().toString(36).slice(2)}
function similarName(a,b){let x=normName(a).replace(/ /g,''),y=normName(b).replace(/ /g,'');if(!x||!y)return false;if(x===y)return true;if(Math.abs(x.length-y.length)>2)return false;let dp=Array.from({length:y.length+1},(_,i)=>i);for(let i=1;i<=x.length;i++){let next=[i];for(let j=1;j<=y.length;j++)next[j]=Math.min(next[j-1]+1,dp[j]+1,dp[j-1]+(x[i-1]===y[j-1]?0:1));dp=next}return dp[y.length]<=2}
function findProfile(name){return store.profiles.find(p=>normName(p.name)===normName(name)||p.aliases?.some(a=>normName(a)===normName(name)))}
function assignProfile(t,m){let name=t.name.trim(),p=findProfile(name);if(!p){let near=store.profiles.filter(p=>similarName(name,p.name));if(near.length){let match=near[0];if(confirm(`Did you mean the existing tipster "${match.name}"?\nOK = use existing profile; Cancel = create a new profile.`))p=match}}
if(!p){p={id:newId(),name,aliases:[]};store.profiles.push(p)}t.profileId=p.id;t.name=p.name;persist();return true}
function duplicateTipsters(m){let seen=new Set,duplicates=[];for(let t of m.tipsters){if(!t.name)continue;let k=t.profileId||normName(t.name);if(seen.has(k))duplicates.push(t.name);seen.add(k)}return duplicates}
function migrate(){let changed=false;store.profiles||=[];for(let m of store.meetings){if(!m.completed)continue;for(let t of m.tipsters){let p=t.profileId&&store.profiles.find(p=>p.id===t.profileId);if(!p){p=findProfile(t.name);if(!p){p={id:newId(),name:t.name,aliases:[]};store.profiles.push(p)}t.profileId=p.id;changed=true}}if(!m.snapshot){m.snapshot=legacySnapshot(m);m.snapshotMigrated=true;changed=true}if(!m.results){m.results=Array.from({length:m.mode==='single'?1:4},()=>['','','','']);changed=true}}if(changed)persist()}
function baseMeetingDetails(){screen='meetingdetails';let m=current;show(title('MEETING HISTORY',m.name,`${m.date} • ${m.mode==='single'?'Single Race':'Quaddie'} • Original predictions locked`)+`<div class="panel"><h3>Original predictions</h3><div class="stack">${button('VIEW ORIGINAL TIPSTER SELECTIONS','originaltips')}${button('VIEW ORIGINAL LEADERBOARDS','leader','secondary')}${button('VIEW ORIGINAL BETTING RECOMMENDATIONS','recommend','secondary')}</div></div><div class="panel"><h3>Actual results & analysis</h3><div class="stack">${button('ENTER / EDIT RACE RESULTS','results')}${button('VIEW PERFORMANCE ANALYSIS','performance','secondary')}</div></div>${m.snapshotMigrated?'<div class="notice">This meeting predates prediction snapshots. Its original selections and recommendations were reconstructed from saved tipster picks during this upgrade.</div>':''}${button('BACK TO HISTORY','history','ghost')}`)}
function originalTips(){screen='originaltips';let m=current,tips=m.snapshot?.tipsters||m.tipsters;show(title('LOCKED ORIGINAL PICKS',m.name,'Read-only historical record')+tips.map((t,i)=>`<div class="panel"><h3>${i+1}. ${escapeHTML(t.name)}</h3>${t.legs.map((p,j)=>`<div class="row"><span>${m.mode==='single'?'Race '+m.race:'Leg '+(j+1)}</span><strong>${p.map(escapeHTML).join(' / ')}</strong></div>`).join('')}</div>`).join('')+button('BACK','meetingdetails','ghost'))}
function completedLeg(m,i){return m.resultStatus?.[i]!=='void'&&hasPositions(m,i,1)}
function ticketHit(ticket,results){return ticket.every((h,i)=>String(Number(h))===String(Number(results[i])))}
function ratio(a,b){return b?`${a}/${b} (${(100*a/b).toFixed(1)}%)`:'No results yet'}
function v42ProfilesPage(){screen='profiles';let rows=store.profiles.map(p=>{let picks=store.meetings.filter(m=>m.completed).flatMap(m=>m.tipsters.filter(t=>t.profileId===p.id).flatMap(t=>t.legs.map((leg,i)=>({m,leg,i}))));let scored=picks.filter(x=>completedLeg(x.m,x.i));let first=scored.filter(x=>String(Number(x.leg[0]))===String(Number(x.m.results[x.i][0]))).length;let covered=scored.filter(x=>x.leg.some(h=>String(Number(h))===String(Number(x.m.results[x.i][0])))).length;return {p,scored:scored.length,first,covered}}).sort((a,b)=>b.scored-a.scored||a.p.name.localeCompare(b.p.name));show(title('TIPSTER PROFILES','Tipster Performance','Linked profiles preserve accuracy statistics across meetings')+`<div class="panel"><h3>${rows.length} saved tipsters</h3><div class="scroll"><table><thead><tr><th>Tipster</th><th>Races</th><th>1st pick wins</th><th>Top 4 coverage</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${escapeHTML(x.p.name)}</td><td>${x.scored}</td><td>${ratio(x.first,x.scored)}</td><td>${ratio(x.covered,x.scored)}</td></tr>`).join('')}</tbody></table></div></div><p class="muted compact">Profiles use unique IDs. Existing names appear as suggestions during entry. A new similar name triggers a warning. Historical picks remain unchanged.</p>${button('BACK','history','ghost')}`)}

// V3: strategy definitions are frozen with each completed meeting.
let strategyMode='',strategyKey='',performanceFilter='kingmick';
function selected(rows){const hit=rows.filter(r=>r.points>=35);return hit.length?hit:rows.filter(r=>r.points===rows[0]?.points)}
function selectionFor(m,i){return m.snapshot?.quaddieSelections?.[i]||selected(board(m,i))}
function boxed(rows,n,positions=n){if(rows.length<n)return [];return permutations(rows.slice(0,n),Array.from({length:n},()=>Array.from({length:positions},(_,i)=>i+1)),positions)}
function advance(dir){capture();const t=draft.tipsters[draft.index],err=validateTip(t);if(dir>0&&err)return alert(err);if(dir>0){assignProfile(t,draft);if(duplicateTipsters(draft).length)return alert('This tipster is already entered in this meeting. Use a different profile.')}if(dir>0&&draft.index===draft.count-1){persist();review();return}draft.index=Math.max(0,draft.index+dir);persist();entry()}
function copyText(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>alert('Copied.')).catch(()=>prompt('Copy these selections:',text));else prompt('Copy these selections:',text)}
