function saveResults(){const m=current,n=m.mode==='single'?1:4,r=Array.from({length:n},()=>['','','','']),status=[],places=[];document.querySelectorAll('[data-result]').forEach(x=>r[+x.dataset.result][+x.dataset.pos]=x.value.trim());document.querySelectorAll('[data-status]').forEach(x=>status[+x.dataset.status]=x.value);document.querySelectorAll('[data-places]').forEach(x=>places[+x.dataset.places]=Number(x.value));for(const [i,leg] of r.entries()){if(leg.some(x=>x&&(!/^\d+$/.test(x)||!Number.isSafeInteger(Number(x))||Number(x)<1)))return alert(`Leg ${i+1}: horse numbers must be positive integers.`);const used=leg.filter(Boolean).map(Number);if(new Set(used).size!==used.length)return alert(`Leg ${i+1}: a horse cannot occupy two finishing positions.`);let blank=false;for(const x of leg){if(!x)blank=true;else if(blank)return alert(`Leg ${i+1}: enter finishing positions in order, without gaps.`)}}m.results=r;m.placeTerms=places;m.resultStatus=status;m.resultsUpdatedAt=Date.now();persist();meetingDetails()}
