function basePerformanceSummary(){const all=store.meetings.flatMap(strategyRecords).filter(r=>!excludeScratchingRecommendations||!r.scratchingAffected),filtered=all.filter(r=>performanceFilter==='all'||(performanceFilter==='multis'?r.id.startsWith('multi'):(r.id.toLowerCase().includes('kingmick')||r.id==='quaddie'))),v3=filtered.filter(r=>r.version==='v3'),legacy=filtered.filter(r=>r.version!=='v3');return `${coverageSummary()}<div class="tabs">${[['kingmick','KingMick bets'],['multis','Multis'],['all','All strategies']].map(([id,l])=>`<button data-a="perf:${id}" class="${performanceFilter===id?'active':''}">${l}</button>`).join('')}</div><div class="panel"><h3>${performanceFilter==='multis'?'KingMick Multis':performanceFilter==='all'?'All Strategies':'KingMick Bets'} · saved rules</h3><p class="muted compact">Every saved strategy is measured automatically against entered results, whether or not you placed a bet. Attempts require all relevant finishing positions; Place multis also require official paid-place terms. Voided races are excluded.</p>${performanceTable(v3)}</div>${legacy.length?`<details class="panel"><summary>Earlier & reconstructed predictions · separate record</summary><p class="muted compact">These use earlier saved rules. Legacy five-position Trifectas and six-position First Fours are excluded. Multis not stored in V2 are reconstructed from the saved boards. This history is kept separate from V3.</p>${performanceTable(legacy)}</details>`:''}<p class="muted compact">Hit rates measure result coverage. Larger combination counts cover more outcomes. Profit tracking is deferred. Position ties and special bookmaker settlement adjustments are not inferred; leave affected results pending until resolved.</p>`}
