function raceOptions(selectedIndex,empty=false){return `${empty?'<option value="">Select race / leg</option>':''}${Array.from({length:legCount()},(_,i)=>`<option value="${i}" ${Number(selectedIndex)===i&&selectedIndex!==''?'selected':''}>${legLabel(current,i)}</option>`).join('')}`}
function raceFields(m){return m.mode==='single'?'':`<div class="field"><label for="quaddieKind">Quaddie type</label><select id="quaddieKind">${[['early','Early Quaddie'],['main','Main Quaddie'],['custom','Other / unspecified']].map(([v,l])=>`<option value="${v}" ${(m.quaddieKind||'custom')===v?'selected':''}>${l}</option>`).join('')}</select></div><p class="muted compact">Enter actual race numbers for these four legs. Daily Double and Treble availability must be checked separately.</p><div class="picks">${Array.from({length:4},(_,i)=>field('Leg '+(i+1)+' race','maprace'+i,m.raceNumbers?.[i]||'','number','min="1"')).join('')}</div>`}
function readRaceFields(m){if(m.mode==='single')return {raceNumbers:[m.race],quaddieKind:'single'};const raceNumbers=Array.from({length:4},(_,i)=>Number(document.querySelector('#maprace'+i).value));if(raceNumbers.some(n=>!Number.isSafeInteger(n)||n<1)||new Set(raceNumbers).size!==4)throw Error('Enter four distinct positive race numbers, one for each Quaddie leg.');return {raceNumbers,quaddieKind:document.querySelector('#quaddieKind').value}}
function setup(){baseSetup();if(draft.mode!=='single')document.querySelector('#count').closest('.field').insertAdjacentHTML('beforebegin',raceFields(draft))}
