function makeSnapshot(m){return {...baseMakeSnapshot(m),appVersion:4,raceNumbers:m.mode==='single'?[m.race]:structuredClone(m.raceNumbers||[]),quaddieKind:m.quaddieKind||'custom'}}
function meetingDetails(){baseMeetingDetails();document.querySelector('main').insertAdjacentHTML('afterbegin',`<div class="panel"><h3>My recorded tickets</h3>${button('REVIEW MY BETS — QUICK CHECKLIST','reviewbets')}${button('MY BETS','mybets','secondary')}${button('RACE NUMBERS & SCRATCHINGS','raceinfo','secondary')}<p class="muted compact">${current.mode==='single'?'Single race':escapeHTML(({early:'Early Quaddie',main:'Main Quaddie',custom:'Quaddie'})[current.quaddieKind]||'Quaddie')} · ${Array.from({length:legCount()},(_,i)=>legLabel(current,i)).join(' / ')}</p></div>`)}
function raceInfo(){screen='raceinfo';show(title('MEETING DETAILS','Races & Scratchings',current.name)+`<div class="panel">${raceFields(current)}<p class="muted compact">Correcting these labels does not change the stored tips, results or original predictions. A scratched horse is flagged; it is never automatically replaced in an actual ticket.</p>${Array.from({length:legCount()},(_,i)=>field(legLabel(current,i)+' — scratched horse numbers','scratched'+i,(current.scratchings?.[i]||[]).join(', '))).join('')}</div>${button('SAVE RACES & SCRATCHINGS','saveraceinfo')}${button('CANCEL','meetingdetails','ghost')}`)}
function parseHorses(text,allowEmpty=false){const raw=String(text||'').trim();if(!raw){if(allowEmpty)return [];throw Error('Enter at least one horse number.')}if(!/^\d+(?:[\s,]+\d+)*$/.test(raw))throw Error('Use positive horse numbers separated by commas or spaces.');const a=raw.split(/[\s,]+/).map(x=>String(Number(x)));if(a.length>100||a.some(x=>!Number.isSafeInteger(Number(x))||Number(x)<1))throw Error('Use up to 100 positive whole horse numbers.');if(new Set(a).size!==a.length)throw Error('A horse is repeated within the same selection list.');return a}
function saveRaceInfo(){try{const info=readRaceFields(current),scratchings=Array.from({length:legCount()},(_,i)=>parseHorses(document.querySelector('#scratched'+i).value,true));Object.assign(current,info,{scratchings});persist();meetingDetails()}catch(e){alert(e.message)}}
function recommendationAffected(m,r){const scratched=i=>new Set((m.scratchings?.[i]||[]).map(String));if(r.leg!==undefined){const s=savedStrategies(m,r.leg).find(s=>s.id===r.id);return !!s?.tickets.some(t=>t.some(h=>scratched(r.leg).has(String(h))))}if(r.id==='quaddie')return m.snapshot.quaddieSelections.some((rows,i)=>rows.some(h=>scratched(i).has(String(h.horse))));const s=(m.snapshot?.multis||multiStrategies(m.snapshot.boards)).find(s=>s.id===r.id);return !!s?.legs.some(l=>scratched(l.index).has(String(l.horse)))}
function strategyRecords(m){return baseStrategyRecords(m).map(r=>({...r,scratchingAffected:recommendationAffected(m,r)}))}
function scratchWarning(){const lists=current.scratchings||[];return lists.some(x=>x.length)?`<div class="notice">Scratchings recorded: ${lists.flatMap((a,i)=>a.length?[`${legLabel(current,i)}: ${a.join(', ')}`]:[]).join('; ')}. Original recommendations remain unchanged. Edit My Bets to match your actual ticket.</div>`:''}
function recommend(){baseRecommend();app.insertAdjacentHTML('afterbegin',scratchWarning())}
function bets(type){baseBets(type);app.insertAdjacentHTML('afterbegin',scratchWarning())}
function multis(){baseMultis();app.insertAdjacentHTML('afterbegin',scratchWarning())}
function quaddiebet(){baseQuaddiebet();app.insertAdjacentHTML('afterbegin',scratchWarning())}
function chooseRace(){return `<div class="field"><label for="racechoice">Race / Quaddie leg</label><select id="racechoice">${Array.from({length:legCount()},(_,i)=>`<option value="${i}" ${i===betRace?'selected':''}>${legLabel(current,i)}</option>`).join('')}</select></div>`}
function resultsPage(){baseResultsPage();document.querySelectorAll('.panel h3').forEach((h,i)=>{if(i<legCount())h.textContent=legLabel(current,i)})}
function daily(){optionalBuilder('daily')}
function treble(){optionalBuilder('treble')}
function showdaily(){generateOptional('daily')}
function showtreble(){generateOptional('treble')}
function optionalBuilder(type){optionalType=type;screen=type;const n=type==='daily'?2:3;show(title('OPTIONAL BET',betNames[type],current.name)+`<div class="notice">Use the races nominated by your bookmaker. They need not be consecutive. Nothing on this screen counts towards performance until you save the ticket and explicitly mark it Won or Lost.</div><div class="panel">${current.mode==='quaddie'&&!current.raceNumbers?.length?button('SET ACTUAL RACE NUMBERS','raceinfo','secondary'):''}${Array.from({length:n},(_,i)=>`<div class="field"><label for="optionalrace${i}">Bet leg ${i+1}</label><select id="optionalrace${i}">${raceOptions(i)}</select></div>`).join('')}<p class="muted compact">Only races entered in this saved meeting are available. If the bookmaker’s product includes other races, enter those races in a separate meeting before using them.</p></div>${button('GENERATE SELECTIONS',type==='daily'?'showdaily':'showtreble')}${button('MY BETS','mybets','secondary')}${button('BACK','recommend','ghost')}`)}
function generateOptional(type){try{const n=type==='daily'?2:3,indices=Array.from({length:n},(_,i)=>Number(document.querySelector('#optionalrace'+i).value));if(new Set(indices).size!==n)throw Error('Select different races for each leg.');if(indices.some(i=>!actualRace(current,i)))throw Error('Set the actual race numbers in Meeting Details first.');myBetDraft=freshBet(type);myBetDraft.label=betNames[type]+' — Races '+indices.map(i=>actualRace(current,i)).join('/');myBetDraft.rows=indices.map(i=>({index:i,horses:selectionFor(current,i).map(r=>String(r.horse))}));myBetDraft.source={id:type,label:betNames[type]+' (optional)',group:type};renderBetEditor()}catch(e){alert(e.message)}}
function freshBet(type){const positions={exacta:2,trifecta:3,firstfour:4}[type]||0;return {id:null,type,label:'My '+betNames[type],mode:positions?'straight':type==='multi'?'multi':'legs',raceIndex:0,positions,slots:Array.from({length:positions},()=>[]),pool:[],tickets:[],rows:Array.from({length:type==='quaddie'?4:type==='treble'?3:2},(_,i)=>({index:i,horses:[],kind:'WIN'})),source:null,settlement:['daily','treble'].includes(type)?'pending':'auto',note:''}}
function newActual(){const type=document.querySelector('#newbettype').value;myBetDraft=freshBet(type);renderBetEditor()}
function v42FromStrategy(i,id){const s=savedStrategies(current,i).find(s=>s.id===id);if(!s||s.legacyInvalid||!s.tickets.length)return alert('This recommendation does not have valid tickets to copy.');myBetDraft=freshBet(s.type);Object.assign(myBetDraft,{label:s.label==='Straight'?betNames[s.type]+' Straight':s.label,raceIndex:i,mode:s.slots?(s.mode==='straight'?'straight':'positional'):'tickets',slots:structuredClone(s.slots||[]),tickets:structuredClone(s.tickets),source:{id:s.id,label:s.label==='Straight'?betNames[s.type]+' Straight':s.mode==='boxed'?betNames[s.type]+' '+s.label:s.label,group:s.id}});if(s.mode==='boxed'&&s.slots){myBetDraft.mode='boxed';myBetDraft.pool=structuredClone(s.slots[0])}renderBetEditor()}
function v42FromQuaddie(){myBetDraft=freshBet('quaddie');myBetDraft.rows=Array.from({length:4},(_,i)=>({index:i,horses:selectionFor(current,i).map(x=>String(x.horse))}));myBetDraft.source={id:'quaddie',label:'KingMick Quaddie',group:'quaddie'};myBetDraft.label='My KingMick Quaddie';renderBetEditor()}
function v42FromMulti(id){const s=(current.snapshot?.multis||multiStrategies(current.snapshot.boards)).find(s=>s.id===id);if(!s)return;myBetDraft=freshBet('multi');myBetDraft.label=s.label;myBetDraft.rows=s.legs.map(l=>({index:l.index,horses:l.horse?[String(l.horse)]:[],kind:s.kind}));myBetDraft.source={id:s.id,label:s.label,group:s.id};renderBetEditor()}
function copyRecommendation(){const [kind,leg,id]=document.querySelector('#recsource').value.split('|');if(kind==='strategy')fromStrategy(Number(leg),id);else if(kind==='quaddie')fromQuaddie();else if(kind==='multi')fromMulti(id)}
function editActual(id){const saved=(current.actualBets||[]).find(b=>b.id===id);if(!saved)return;myBetDraft=structuredClone(saved);renderBetEditor()}
function orderCount(slots){let dp=Array(1<<slots.length).fill(0);dp[0]=1;for(const h of new Set(slots.flat())){const next=dp.slice();for(let mask=0;mask<dp.length;mask++)if(dp[mask])for(let i=0;i<slots.length;i++)if(!(mask&(1<<i))&&slots[i].includes(h))next[mask|(1<<i)]+=dp[mask];dp=next}return dp.at(-1)}
function actualCombos(b){if(b.type==='multi')return 1;if(b.positions){if(b.mode==='tickets')return b.tickets.length;if(b.mode==='boxed')return Array.from({length:b.positions},(_,i)=>b.pool.length-i).reduce((a,n)=>a*Math.max(0,n),1);return orderCount(b.slots)}return b.rows.reduce((n,r)=>n*r.horses.length,1)}
function captureBetEditor(strict=true){const b=structuredClone(myBetDraft);b.label=document.querySelector('#betlabel').value.trim();b.note=document.querySelector('#betnote').value.trim();b.settlement=document.querySelector('#betsettlement').value;if(!b.label)throw Error('Give this ticket a name.');const parse=(v)=>parseHorses(v,!strict);if(b.positions){b.raceIndex=Number(document.querySelector('#actualrace').value);if(b.mode==='boxed')b.pool=parse(document.querySelector('#betpool').value);else if(b.mode==='tickets'){b.tickets=document.querySelector('#bettickets').value.trim().split('\n').filter(x=>x.trim()).map(line=>parseHorses(line));if(b.tickets.length>5000)throw Error('Use up to 5,000 explicit combinations per ticket.');if(b.tickets.some(t=>t.length!==b.positions))throw Error(`Each combination must contain exactly ${b.positions} different horse numbers.`);const keys=b.tickets.map(t=>t.join(','));if(new Set(keys).size!==keys.length)throw Error('The same combination appears more than once.')}else{b.slots=Array.from({length:b.positions},(_,i)=>parse(document.querySelector('#betslot'+i).value));if(strict&&b.mode==='straight'&&b.slots.some(s=>s.length!==1))throw Error('A straight ticket needs exactly one horse in each finishing position.')}}else b.rows=Array.from(document.querySelectorAll('[data-betrow]')).map(el=>({index:Number(el.querySelector('select[data-leg]').value),horses:parse(el.querySelector('input[data-horses]').value),kind:el.querySelector('select[data-kind]')?.value||'WIN'}));validateActual(b,strict);return b}
function validateActual(b,strict=true){if(!Object.hasOwn(betNames,b.type))throw Error('Choose a supported bet type.');if(!['auto','hit','miss','pending','void'].includes(b.settlement))throw Error('Choose a valid settlement status.');if(['daily','treble'].includes(b.type)&&b.settlement==='auto')throw Error('Daily Double and Treble outcomes must be marked manually.');const indices=b.positions?[b.raceIndex]:b.rows.map(r=>r.index);if(indices.some(i=>!Number.isInteger(i)||i<0||i>=legCount()))throw Error('A selected race is outside this saved meeting.');if(!b.positions&&new Set(indices).size!==indices.length)throw Error('Select different races for every leg of this ticket.');if(['daily','treble'].includes(b.type)&&indices.some(i=>!actualRace(current,i)))throw Error('Set actual race numbers before saving an optional bet.');if(b.type==='quaddie'&&(indices.length!==4||new Set(indices).size!==4))throw Error('A Quaddie needs all four meeting legs.');if(b.type==='multi'&&(b.rows.length<2||b.rows.length>4||b.rows.some(r=>(strict?r.horses.length!==1:r.horses.length>1)||!['WIN','PLACE'].includes(r.kind))))throw Error('A multi needs two to four different races, with one horse and Win/Place per leg.');if(strict&&actualCombos(b)<1)throw Error('These selections do not make a valid combination. Check the horse numbers and finishing positions.')}
function renderBetEditor(){screen='actualeditor';const b=myBetDraft,optional=['daily','treble'].includes(b.type);show(title('MY ACTUAL BETS',b.id?'Edit saved ticket':'Record a ticket',current.name)+`<div class="notice compact">Save only tickets you actually placed. Check every selection against your bookmaker receipt. Original predictions stay locked.</div><div class="panel">${field('Ticket name','betlabel',b.label)}<p class="muted compact">${escapeHTML(betNames[b.type])}${b.source?' · Based on '+escapeHTML(b.source.label):' · Custom ticket'}</p>${b.positions?`<div class="field"><label for="actualrace">Race</label><select id="actualrace">${raceOptions(b.raceIndex)}</select></div><div class="field"><label for="betmode">Ticket style</label><select id="betmode">${[['straight','Straight'],['boxed','Boxed'],['positional','Position selections'],['tickets','Explicit combinations']].map(([v,l])=>`<option value="${v}" ${b.mode===v?'selected':''}>${l}</option>`).join('')}</select><p class="muted compact">Changing style can change the combinations. Match the selections to your actual ticket.</p></div>${b.mode==='boxed'?field('Boxed horses (comma or space separated)','betpool',b.pool.join(', ')):b.mode==='tickets'?`<div class="field"><label for="bettickets">One ordered combination per line · ${b.positions} horses per line</label><textarea id="bettickets" rows="8">${escapeHTML(b.tickets.map(t=>t.join(', ')).join('\n'))}</textarea></div>`:b.slots.map((s,i)=>field(finishNames[i]+' place horse'+(b.mode==='straight'?'':'s'),'betslot'+i,s.join(', '))).join('')}`:b.rows.map((r,i)=>`<div class="bet-leg" data-betrow="${i}"><h3>Ticket leg ${i+1}</h3><div class="field"><label for="ticketleg${i}">Race / Quaddie leg</label><select id="ticketleg${i}" data-leg>${raceOptions(r.index)}</select></div><div class="field"><label for="tickethorses${i}">${b.type==='multi'?'Horse number':'Selected horse numbers'}</label><input id="tickethorses${i}" data-horses value="${escapeHTML(r.horses.join(', '))}" inputmode="${b.type==='multi'?'numeric':'text'}"></div>${b.type==='multi'?`<div class="field"><label for="ticketkind${i}">Selection must</label><select id="ticketkind${i}" data-kind><option value="WIN" ${r.kind==='WIN'?'selected':''}>Win</option><option value="PLACE" ${r.kind==='PLACE'?'selected':''}>Place</option></select></div>${b.rows.length>2?button('REMOVE THIS LEG','actual:removeleg:'+i,'ghost'):''}`:''}</div>`).join('')}${b.type==='multi'&&b.rows.length<Math.min(4,legCount())?button('ADD MULTI LEG','actual:addleg','secondary'):''}<div class="field"><label for="betsettlement">Outcome</label><select id="betsettlement">${[...(!optional?[['auto','Automatic — use results']]:[]),['pending','Pending — exclude from attempts'],['hit','Won'],['miss','Lost'],['void','Void — exclude from attempts']].map(([v,l])=>`<option value="${v}" ${b.settlement===v?'selected':''}>${l}</option>`).join('')}</select></div><p class="muted compact">${optional?'Daily Double / Treble: explicitly choose Won or Lost after settlement. Race results never override this choice.':'Automatic assessment uses the saved selections and entered results. Place selections also require official paid-place terms. You may record a manual outcome to match bookmaker settlement.'}</p>${field('Notes (optional)','betnote',b.note||'')}<p class="muted compact">Current draft: ${actualCombos(b)} combination(s). Saving validates and recalculates this count.</p></div><details class="panel"><summary>Replace a scratched horse</summary><p class="muted compact">This changes this ticket only, keeping the same finishing positions. The scratching is also flagged in the meeting when you save.</p><div class="picks two">${field('Scratched horse','replacefrom','','number','min="1"')}${field('Replacement horse','replaceto','','number','min="1"')}</div><div class="field"><label for="replaceleg">Affected race</label><select id="replaceleg">${raceOptions(b.positions?b.raceIndex:'',true)}</select></div>${button('APPLY REPLACEMENT TO DRAFT','actual:replace','secondary')}</details>${button('SAVE AS PLACED BET','saveactual')}${button('CANCEL','mybets','ghost')}`)}
function changeBetMode(){const next=document.querySelector('#betmode').value;try{const b=captureBetEditor(false),old=b.mode,pool=old==='boxed'?b.pool:old==='tickets'?[...new Set(b.tickets.flat())]:[...new Set(b.slots.flat())];b.mode=next;if(next==='boxed')b.pool=pool;else if(next==='tickets')b.tickets=old==='tickets'?b.tickets:enumerateActual(b,old);else b.slots=old==='boxed'?Array.from({length:b.positions},()=>pool.slice()):old==='tickets'?Array.from({length:b.positions},(_,i)=>[...new Set(b.tickets.map(t=>t[i]))]):b.slots;myBetDraft=b;renderBetEditor()}catch(e){document.querySelector('#betmode').value=myBetDraft.mode;alert(e.message)}}
function enumerateActual(b,mode=b.mode){const slots=mode==='boxed'?Array.from({length:b.positions},()=>b.pool):b.slots;if(orderCount(slots)>5000)throw Error('This ticket has more than 5,000 combinations. Keep it as Boxed or Position selections.');const out=[];function next(i,t){if(i===b.positions){out.push(t);return}for(const h of slots[i])if(!t.includes(h))next(i+1,[...t,h])}next(0,[]);return out}
function replaceDraftHorse(){try{const b=captureBetEditor(false),old=parseHorses(document.querySelector('#replacefrom').value),next=parseHorses(document.querySelector('#replaceto').value),scope=document.querySelector('#replaceleg').value;if(scope==='')throw Error('Select the race containing the scratched horse.');if(old.length!==1||next.length!==1||old[0]===next[0])throw Error('Enter one scratched horse and one different replacement horse.');let changed=false;const staged=[];function swap(list,index){if(scope!=='all'&&Number(scope)!==index)return list;if(!list.includes(old[0]))return list;changed=true;staged.push({index,horse:old[0]});return [...new Set(list.map(h=>h===old[0]?next[0]:h))]}
if(b.positions){if(b.mode==='boxed')b.pool=swap(b.pool,b.raceIndex);else if(b.mode==='tickets'){b.tickets=b.tickets.map(t=>{if(scope!=='all'&&Number(scope)!==b.raceIndex)return t;if(t.includes(old[0])){changed=true;staged.push({index:b.raceIndex,horse:old[0]})}return t.map(h=>h===old[0]?next[0]:h)}).filter(t=>new Set(t).size===t.length);b.tickets=[...new Map(b.tickets.map(t=>[t.join(','),t])).values()]}else b.slots=b.slots.map(s=>swap(s,b.raceIndex))}else b.rows=b.rows.map(r=>({...r,horses:swap(r.horses,r.index)}));if(!changed)throw Error('That horse was not selected in the chosen race(s) on this ticket.');b.pendingScratchings=[...(b.pendingScratchings||[]),...staged];b.note=(b.note?b.note+' · ':'')+`Replaced ${old[0]} with ${next[0]} (${scope==='all'?'all used races':legLabel(current,Number(scope))}).`;myBetDraft=b;renderBetEditor()}catch(e){alert(e.message)}}
function changeMultiLeg(action,index){try{const b=captureBetEditor(false);if(action==='add'&&b.rows.length<Math.min(4,legCount())){const unused=Array.from({length:legCount()},(_,i)=>i).find(i=>!b.rows.some(r=>r.index===i));b.rows.push({index:unused,horses:[],kind:'WIN'})}if(action==='remove'&&b.rows.length>2)b.rows.splice(index,1);myBetDraft=b;renderBetEditor()}catch(e){alert(e.message)}}
function v41SaveActual(){try{const b=captureBetEditor();b.id||=newId();b.createdAt||=Date.now();b.updatedAt=Date.now();current.actualBets||=[];const index=current.actualBets.findIndex(x=>x.id===b.id);for(const s of b.pendingScratchings||[]){current.scratchings||=Array.from({length:legCount()},()=>[]);current.scratchings[s.index]||=[];if(!current.scratchings[s.index].includes(s.horse))current.scratchings[s.index].push(s.horse)}delete b.pendingScratchings;if(index<0)current.actualBets.push(b);else current.actualBets[index]=b;persist();myBetDraft=null;myBets()}catch(e){alert(e.message)}}
function calculateActual(m,b){let correct=0,total=b.positions?1:b.rows.length;const indices=b.positions?[b.raceIndex]:b.rows.map(r=>r.index);if(indices.some(i=>m.resultStatus?.[i]==='void'))return {state:'void',correct,total};if(b.positions){if(!hasPositions(m,b.raceIndex,b.positions))return {state:'pending',correct,total};const result=m.results[b.raceIndex].slice(0,b.positions).map(x=>String(Number(x)));const hit=b.mode==='boxed'?result.every(h=>b.pool.includes(h)):b.mode==='tickets'?b.tickets.some(t=>ticketHit(t,result)):result.every((h,i)=>b.slots[i].includes(h));return {state:hit?'hit':'miss',correct:hit?1:0,total}}
let pending=false;for(const r of b.rows){const need=b.type==='multi'&&r.kind==='PLACE'?Number(m.placeTerms?.[r.index]||0):1;if(!need||!hasPositions(m,r.index,need)){pending=true;continue}if(m.results[r.index].slice(0,need).some(h=>r.horses.some(x=>sameHorse(x,h))))correct++}return {state:pending?'pending':correct===total?'hit':'miss',correct,total}}
function assessActual(m,b){const calculated=calculateActual(m,b);return {...calculated,calculatedState:calculated.state,state:b.settlement==='auto'?calculated.state:b.settlement,manual:b.settlement!=='auto'}}
function outcomeLabel(state){return ({hit:'WON',miss:'LOST',pending:'PENDING',void:'VOID'})[state]||'PENDING'}
function actualRecords(m){return (m.actualBets||[]).map(b=>{const a=assessActual(m,b),group=b.source?.group||(['daily','treble'].includes(b.type)?b.type:b.type+':'+b.mode);return {...a,id:'actual:'+group,label:escapeHTML(['daily','treble'].includes(b.type)?betNames[b.type]+' (optional)':b.source?.label||betNames[b.type]+(b.positions?' · '+b.mode:'')),version:'actual',date:m.finalizedAt||b.createdAt,combos:actualCombos(b),betId:b.id,meetingId:m.id}})}
function ticketSelections(m,b){if(b.positions){if(b.mode==='boxed')return `${legLabel(m,b.raceIndex)} · Boxed: ${b.pool.join(', ')}`;if(b.mode==='tickets')return `${legLabel(m,b.raceIndex)} · ${b.tickets.length} explicit combinations`;return `${legLabel(m,b.raceIndex)} · ${b.slots.map((s,i)=>finishNames[i]+': '+s.join(', ')).join(' / ')}`}return b.rows.map(r=>`${legLabel(m,r.index)}: ${r.horses.join(', ')}${b.type==='multi'?' '+r.kind:''}`).join(' + ')}
function myBets(){screen='mybets';myBetDraft=null;const m=current,bets=m.actualBets||[],records=actualRecords(m),done=records.filter(r=>['hit','miss'].includes(r.state)),won=done.filter(r=>r.state==='hit').length;const sources=[];for(let i=0;i<legCount();i++)for(const s of savedStrategies(m,i))if(s.tickets.length&&!s.legacyInvalid)sources.push([`strategy|${i}|${s.id}`,`${legLabel(m,i)} · ${s.label==='Straight'?betNames[s.type]+' Straight':s.label}`]);if(m.mode==='quaddie'){sources.unshift(['quaddie||','KingMick Quaddie']);for(const s of m.snapshot?.multis||multiStrategies(m.snapshot.boards))sources.push([`multi||${s.id}`,s.label])}show(title('MY ACTUAL BETS',m.name,'Tickets you explicitly recorded as placed')+button('QUICK REVIEW OF ORIGINAL RECOMMENDATIONS','reviewbets')+`<div class="panel"><h3>${won} ${won===1?'win':'wins'} from ${done.length} settled ${done.length===1?'ticket':'tickets'}</h3><p class="muted compact">${ratio(won,done.length)} · ${records.filter(r=>r.state==='pending').length} pending · ${records.filter(r=>r.state==='void').length} void. Original recommendations are measured separately.</p></div>${scratchWarning()}${bets.map(b=>{const a=assessActual(m,b);return `<div class="panel"><div class="row"><h3>${escapeHTML(b.label)}</h3><strong class="${a.state==='hit'?'good':a.state==='miss'?'bad':'muted'}">${outcomeLabel(a.state)}</strong></div><p>${escapeHTML(ticketSelections(m,b))}</p><p class="muted compact">${actualCombos(b)} combination(s) · ${a.manual?'Manually recorded outcome':'Automatically checked against results'}${!b.positions?' · '+a.correct+' of '+a.total+' legs confirmed by results':''}</p>${a.manual&&a.calculatedState!==a.state?`<p class="muted compact">Entered results currently indicate ${outcomeLabel(a.calculatedState)}; your manual outcome is used.</p>`:''}${b.note?`<p class="compact">${escapeHTML(b.note)}</p>`:''}${button('EDIT TICKET / OUTCOME','actual:edit:'+b.id,'secondary')}${button('DELETE TICKET','actual:delete:'+b.id,'ghost')}</div>`}).join('')||'<div class="panel muted">No placed bets recorded yet. Copy a recommendation or add your own ticket below.</div>'}<div class="panel"><h3>Copy a recommendation</h3><p class="muted compact">Make any changes, then save to confirm you placed the ticket.</p><div class="field"><label for="recsource">Saved recommendation</label><select id="recsource">${sources.map(([v,l])=>`<option value="${escapeHTML(v)}">${escapeHTML(l)}</option>`).join('')}</select></div>${sources.length?button('COPY & EDIT RECOMMENDATION','actual:copy','secondary'):'<p>No valid recommendations to copy.</p>'}</div><div class="panel"><h3>Add a custom ticket</h3><div class="field"><label for="newbettype">Bet type</label><select id="newbettype">${Object.entries(betNames).filter(([type])=>m.mode==='quaddie'||['exacta','trifecta','firstfour'].includes(type)).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div>${button('ADD TICKET','actual:new')}${m.mode==='quaddie'?`<div class="actions">${button('OPTIONAL DAILY DOUBLE','daily','secondary')}${button('OPTIONAL TREBLE','treble','secondary')}</div>`:''}</div>${button('ENTER / EDIT RESULTS','results')}${button('RACE NUMBERS & SCRATCHINGS','raceinfo','secondary')}${button('PERFORMANCE','actualstats','secondary')}${button('BACK TO MEETING','meetingdetails','ghost')}`)}
function performanceSummary(){const nav=`<div class="tabs"><button data-a="view:original" class="${performanceView==='original'?'active':''}">Original recommendations</button><button data-a="view:actual" class="${performanceView==='actual'?'active':''}">My Actual Bets</button></div>`;if(performanceView==='actual'){const records=store.meetings.flatMap(actualRecords);return nav+`<div class="panel"><h3>My Actual Bets</h3><p class="muted compact">Only tickets you explicitly saved as placed are included. Won + Lost form the attempt count; Pending and Void are excluded. Each ticket counts once, regardless of its combinations. Optional Daily Doubles and Trebles require your manual outcome.</p>${performanceTable(records)}</div>`}return nav+`<div class="panel"><h3>Scratching filter</h3><p class="muted compact">Original recommendations stay unchanged. You can exclude recommendations containing a recorded scratched horse from this view.</p>${button(excludeScratchingRecommendations?'SHOW ALL ORIGINAL RECOMMENDATIONS':'EXCLUDE SCRATCHING-AFFECTED RECOMMENDATIONS','scratchfilter','secondary')}<p class="compact">${excludeScratchingRecommendations?'Scratching-affected recommendations excluded.':'All original recommendations included.'}</p><p class="muted compact">Daily Doubles and Trebles are optional and are tracked only under My Actual Bets after a manually recorded Won / Lost outcome.</p></div>`+basePerformanceSummary()}
function meetingPerformance(){baseMeetingPerformance();const records=strategyRecords(current);document.querySelectorAll('.result-card').forEach((el,i)=>{if(records[i]?.scratchingAffected)el.insertAdjacentHTML('beforeend','<p class="notice compact">Scratching affected — original recommendation unchanged.</p>')});app.insertAdjacentHTML('afterbegin',button('VIEW MY ACTUAL BETS','mybets','secondary')+scratchWarning())}
function v41Dispatch(a){if(a==='mybets')return myBets();if(a==='raceinfo')return raceInfo();if(a==='saveraceinfo')return saveRaceInfo();if(a==='saveactual')return saveActual();if(a==='actualstats'){performanceView='actual';return stats()}if(a==='scratchfilter'){excludeScratchingRecommendations=!excludeScratchingRecommendations;return stats()}if(a.startsWith('view:')){performanceView=a.slice(5);return stats()}if(a==='actual:new')return newActual();if(a==='actual:copy')return copyRecommendation();if(a==='actual:strategy'){const s=currentStrategy();if(s)return fromStrategy(betRace,s.id);return}if(a==='actual:quaddie')return fromQuaddie();if(a.startsWith('actual:multi:'))return fromMulti(a.slice(13));if(a.startsWith('actual:edit:'))return editActual(a.slice(12));if(a.startsWith('actual:delete:')){if(confirm('Delete this recorded ticket? Original recommendations will remain unchanged.')){current.actualBets=(current.actualBets||[]).filter(b=>b.id!==a.slice(14));persist();myBets()}return}if(a==='actual:replace')return replaceDraftHorse();if(a==='actual:addleg')return changeMultiLeg('add');if(a.startsWith('actual:removeleg:'))return changeMultiLeg('remove',Number(a.slice(17)));return baseDispatch(a)}
app.addEventListener('change',e=>{if(e.target.id==='betmode')changeBetMode()});


// V4.2: one-tap review of original recommendations, linked to actual tickets.
let reviewFilter='kingmick',reviewRace='all',reviewSelected=new Set(),reviewReturn=false;
function reviewRows(m=current){const rows=[];if(m.mode==='quaddie')rows.push({key:'quaddie',kind:'quaddie',label:'KingMick Quaddie',special:true});for(let i=0;i<legCount(m);i++)for(const s of savedStrategies(m,i))if(s.tickets.length&&!s.legacyInvalid)rows.push({key:`race:${i}:${s.id}`,kind:'race',leg:i,id:s.id,label:s.label==='Straight'?betNames[s.type]+' Straight':s.mode==='boxed'?betNames[s.type]+' '+s.label:s.label,special:s.mode==='kingmick'});if(m.mode==='quaddie')for(const s of m.snapshot?.multis||multiStrategies(m.snapshot.boards))if(s.legs.every(l=>l.horse))rows.push({key:'multi:'+s.id,kind:'multi',id:s.id,label:s.label,special:false});return rows}
function reviewTemplate(row,m=current){let b;if(row.kind==='quaddie'){b=freshBet('quaddie');b.rows=Array.from({length:4},(_,i)=>({index:i,horses:selectionFor(m,i).map(r=>String(r.horse))}));b.label='My KingMick Quaddie';b.source={id:'quaddie',group:'quaddie',label:row.label}}else if(row.kind==='multi'){const s=(m.snapshot?.multis||multiStrategies(m.snapshot.boards)).find(s=>s.id===row.id);b=freshBet('multi');b.rows=s.legs.map(l=>({index:l.index,horses:[String(l.horse)],kind:s.kind}));b.label=row.label;b.source={id:s.id,group:s.id,label:row.label}}else{const s=savedStrategies(m,row.leg).find(s=>s.id===row.id);b=freshBet(s.type);Object.assign(b,{label:row.label,raceIndex:row.leg,mode:s.slots?(s.mode==='straight'?'straight':s.mode==='boxed'?'boxed':'positional'):'tickets',slots:structuredClone(s.slots||[]),tickets:s.slots?[]:structuredClone(s.tickets),pool:s.mode==='boxed'&&s.slots?s.slots[0].slice():[],source:{id:s.id,group:s.id,label:row.label}})}b.reviewKey=row.key;return b}
function ticketSignature(b){if(b.positions){const tickets=b.mode==='tickets'?b.tickets:enumerateActual(b);return JSON.stringify([b.type,b.raceIndex,tickets.map(t=>t.map(String).join(',')).sort()])}return JSON.stringify([b.type,b.rows.map(r=>[r.index,r.horses.map(String).slice().sort((a,c)=>Number(a)-Number(c)),b.type==='multi'?r.kind:'WIN']).sort((a,c)=>a[0]-c[0])])}
function explicitReviewKey(b){if(b.reviewKey)return b.reviewKey;if(!b.source?.id)return null;if(b.type==='quaddie'&&b.source.id==='quaddie')return 'quaddie';if(b.type==='multi')return 'multi:'+b.source.id;if(b.positions)return `race:${b.raceIndex}:${b.source.id}`;return null}
function reviewLinks(rows=reviewRows(),m=current){const links=new Map(rows.map(r=>[r.key,[]])),unlinked=[],tickets=m.actualBets||[];for(const b of tickets){const key=explicitReviewKey(b);if(links.has(key))links.get(key).push(b);else unlinked.push(b)}const signatures=new Map();for(const r of rows){try{const sig=ticketSignature(reviewTemplate(r,m));if(!signatures.has(sig))signatures.set(sig,[]);signatures.get(sig).push(r.key)}catch{}}
const unmatched=[];for(const b of unlinked){let candidates;try{candidates=signatures.get(ticketSignature(b))}catch{}const key=candidates?.find(k=>!links.get(k).length);if(key)links.get(key).push(b);else unmatched.push(b)}return {links,unmatched}}
function filteredReviewRows(rows){return rows.filter(r=>(reviewFilter==='all'||(reviewFilter==='multis'?r.kind==='multi':r.special))&&(reviewRace==='all'||r.leg===Number(reviewRace)))}
function reviewRowSummary(row){const b=reviewTemplate(row);return ticketSelections(current,b)}
function reviewOriginalHTML(row){const b=reviewTemplate(row);return `<p class="compact">${escapeHTML(ticketSelections(current,b))}</p>${b.mode==='tickets'?`<ol class="tickets">${b.tickets.map(t=>`<li>${t.map(escapeHTML).join(' → ')}</li>`).join('')}</ol>`:''}`}
function v42ReviewBets(){screen='reviewbets';myBetDraft=null;const rows=reviewRows(),{links,unmatched}=reviewLinks(rows),visible=filteredReviewRows(rows),records=(current.actualBets||[]).map(b=>assessActual(current,b)),settled=records.filter(r=>['hit','miss'].includes(r.state)),won=settled.filter(r=>r.state==='hit').length;show(title('QUICK BET REVIEW',current.name,'Mark the original recommendations you actually placed')+`<div class="panel"><h3>${won} wins from ${settled.length} settled tickets</h3><p class="muted compact">Won / Lost confirms you placed this ticket unchanged. Pending means placed but not yet settled. Didn’t Place creates no actual ticket. Use Changed This Bet for substitutions or tweaks.</p>${unmatched.length?`<div class="notice">${unmatched.length} existing ticket(s) could not be matched automatically. Use “Link Existing Ticket” on the corresponding recommendation before recording it again. Linking keeps its selections and outcome.</div>`:''}</div><div class="tabs">${[['kingmick','KingMick'],['multis','Multis'],['all','All bets']].map(([v,l])=>`<button data-a="reviewfilter:${v}" class="${reviewFilter===v?'active':''}">${l}</button>`).join('')}</div><div class="field"><label for="reviewrace">Show race</label><select id="reviewrace"><option value="all">All races & multi-race bets</option>${Array.from({length:legCount()},(_,i)=>`<option value="${i}" ${reviewRace===String(i)?'selected':''}>${legLabel(current,i)}</option>`).join('')}</select></div><div class="panel bulk-review"><h3>Quickly record losing tickets</h3><p class="muted compact">Select the unrecorded recommendations you placed, then mark them Lost together. Existing tickets and Didn’t Place choices are protected.</p><div class="actions">${button('SELECT AVAILABLE ROWS','reviewselect','secondary')}${button('CLEAR SELECTION','reviewclear','ghost')}</div><button class="btn" data-a="reviewbulk" id="reviewbulk" ${reviewSelected.size?'':'disabled'}>MARK ${reviewSelected.size} SELECTED AS LOST</button></div>${visible.map(r=>{const bets=links.get(r.key)||[],notPlaced=current.betReview?.[r.key]==='notplaced',status=bets.length===1?outcomeLabel(assessActual(current,bets[0]).state):bets.length>1?bets.length+' RECORDED TICKETS':notPlaced?'DIDN’T PLACE':'NOT RECORDED';let changed=false;if(bets.length===1){try{changed=ticketSignature(bets[0])!==ticketSignature(reviewTemplate(r))}catch{changed=true}}return `<section class="panel review-card" data-review-row="${r.key}"><div class="row"><h3>${r.leg!==undefined?legLabel(current,r.leg)+' · ':''}${escapeHTML(r.label)}</h3><label class="review-check"><input type="checkbox" data-review-select="${r.key}" aria-label="Select ${escapeHTML(r.label)}${r.leg!==undefined?' '+legLabel(current,r.leg):''} for bulk loss" ${bets.length||notPlaced?'disabled':''} ${reviewSelected.has(r.key)?'checked':''}><span>Select</span></label></div><p class="review-status">${status}${bets.length?' · already recorded':''}${changed?' · changed selections':''}</p><details><summary>View original selections</summary>${reviewOriginalHTML(r)}</details>${bets.length>1?bets.map(b=>`<p>${escapeHTML(b.label)} · ${outcomeLabel(assessActual(current,b).state)}</p>${button('EDIT THIS RECORDED TICKET','reviewedit:'+b.id,'secondary')}`).join(''):`<div class="review-actions">${button('WON','reviewmark:hit:'+r.key,'secondary')}${button('LOST','reviewmark:miss:'+r.key,'secondary')}${button('PENDING','reviewmark:pending:'+r.key,'secondary')}<button class="btn ghost" data-a="reviewmark:notplaced:${r.key}" ${bets.length?'disabled':''}>DIDN’T PLACE</button></div>${button(changed?'EDIT CHANGED TICKET':'CHANGED THIS BET','reviewchange:'+r.key,'ghost')}`}${notPlaced&&!bets.length?button('RESET DIDN’T PLACE','reviewreset:'+r.key,'ghost'):''}${unmatched.some(b=>b.type===reviewTemplate(r).type&&(b.positions?b.raceIndex===r.leg:true))?button('LINK EXISTING TICKET','reviewlink:'+r.key,'ghost'):''}</section>`}).join('')||'<div class="panel muted">No recommendations match this filter.</div>'}<div class="panel"><h3>Optional Daily Double / Treble</h3><p class="muted compact">These are not assumed to be available. Configure their actual races and manually record their outcome in My Bets.</p>${button('MY BETS & OPTIONAL TICKETS','mybets','secondary')}</div>${button('MY ACTUAL BETS PERFORMANCE','actualstats','secondary')}${button('BACK TO MEETING','meetingdetails','ghost')}`)}
function reviewMark(key,state,persistNow=true){const row=reviewRows().find(r=>r.key===key);if(!row)return;const bets=reviewLinks().links.get(key)||[];current.betReview||={};if(state==='notplaced'){if(bets.length)return;current.betReview[key]='notplaced'}else{if(!['hit','miss','pending'].includes(state))return;if(bets.length>1)return alert('This recommendation has multiple recorded tickets. Edit their outcomes individually.');const b=bets[0]||reviewTemplate(row);if(!b.id){b.id=newId();b.createdAt=Date.now();current.actualBets||=[];current.actualBets.push(b)}b.reviewKey=key;b.source=reviewTemplate(row).source;b.settlement=state;b.updatedAt=Date.now();delete current.betReview[key]}reviewSelected.delete(key);if(persistNow){persist();reviewBets()}}
function reviewBulk(){const rows=filteredReviewRows(reviewRows()),{links}=reviewLinks(),keys=rows.filter(r=>reviewSelected.has(r.key)&&!links.get(r.key)?.length&&current.betReview?.[r.key]!=='notplaced').map(r=>r.key);for(const key of keys)reviewMark(key,'miss',false);reviewSelected.clear();persist();reviewBets()}
function v42ReviewChange(key){const row=reviewRows().find(r=>r.key===key);if(!row)return;const bets=reviewLinks().links.get(key)||[];reviewReturn=true;if(bets.length===1){editActual(bets[0].id);myBetDraft.reviewKey=key;myBetDraft.source=reviewTemplate(row).source}else{myBetDraft=reviewTemplate(row);renderBetEditor()}}
function reviewLinkPage(key){const row=reviewRows().find(r=>r.key===key);if(!row)return;const type=reviewTemplate(row).type,{unmatched}=reviewLinks();screen='reviewlink';show(title('LINK EXISTING TICKET',row.label,'Associate a ticket you already entered; selections and outcome stay intact.')+`<div class="panel"><div class="field"><label for="reviewexisting">Existing ticket</label><select id="reviewexisting">${unmatched.filter(b=>b.type===type&&(!b.positions||b.raceIndex===row.leg)).map(b=>`<option value="${b.id}">${escapeHTML(b.label)} · ${outcomeLabel(assessActual(current,b).state)}</option>`).join('')}</select></div>${button('LINK THIS TICKET','reviewattach:'+key)}</div>${button('CANCEL','reviewbets','ghost')}`)}
function v42ReviewAttach(key){const row=reviewRows().find(r=>r.key===key),id=document.querySelector('#reviewexisting').value,b=(current.actualBets||[]).find(b=>b.id===id);if(!row||!b)return;const expected=reviewTemplate(row);if(b.type!==expected.type||(b.positions&&b.raceIndex!==row.leg))return alert('That ticket belongs to another bet type or race.');b.reviewKey=key;b.source=expected.source;current.betReview||={};delete current.betReview[key];persist();reviewBets()}
function v42SaveActual(){const returnToReview=reviewReturn;v41SaveActual();if(screen==='mybets'){reviewReturn=false;if(returnToReview)reviewBets()}}
function v42Dispatch(a){if(a==='reviewbets'){reviewReturn=false;return reviewBets()}if(a==='mybets'&&screen==='actualeditor'&&reviewReturn){reviewReturn=false;return reviewBets()}if(a.startsWith('reviewfilter:')){reviewFilter=a.slice(13);reviewSelected.clear();return reviewBets()}if(a.startsWith('reviewmark:')){const rest=a.slice(11),split=rest.indexOf(':');return reviewMark(rest.slice(split+1),rest.slice(0,split))}if(a.startsWith('reviewchange:'))return reviewChange(a.slice(13));if(a.startsWith('reviewedit:')){reviewReturn=true;return editActual(a.slice(11))}if(a.startsWith('reviewlink:'))return reviewLinkPage(a.slice(11));if(a.startsWith('reviewattach:'))return reviewAttach(a.slice(13));if(a.startsWith('reviewreset:')){delete current.betReview?.[a.slice(12)];persist();return reviewBets()}if(a==='reviewselect'){const {links}=reviewLinks();for(const r of filteredReviewRows(reviewRows()))if(!links.get(r.key).length&&current.betReview?.[r.key]!=='notplaced')reviewSelected.add(r.key);return reviewBets()}if(a==='reviewclear'){reviewSelected.clear();return reviewBets()}if(a==='reviewbulk')return reviewBulk();return v41Dispatch(a)}
app.addEventListener('change',e=>{if(e.target.id==='reviewrace'){reviewRace=e.target.value;reviewSelected.clear();reviewBets()}if(e.target.matches('[data-review-select]')){const key=e.target.dataset.reviewSelect;e.target.checked?reviewSelected.add(key):reviewSelected.delete(key);const btn=document.querySelector('#reviewbulk');btn.textContent=`MARK ${reviewSelected.size} SELECTED AS LOST`;btn.disabled=!reviewSelected.size}});


// V4.3: straightforward results, protected profile cleanup and compact review.
function resultTotals(records){const settled=records.filter(r=>['hit','miss'].includes(r.state)),wins=settled.filter(r=>r.state==='hit').length;return {wins,settled:settled.length,pending:records.filter(r=>r.state==='pending').length,voided:records.filter(r=>['void','unavailable'].includes(r.state)).length,pct:settled.length?(wins*100/settled.length).toFixed(1)+'%':'—'}}
function totalsHTML(records){const t=resultTotals(records);return `<div class="panel result-summary"><div class="metric">${t.wins} ${t.wins===1?'win':'wins'}<small> from ${t.settled} settled ${t.settled===1?'bet':'bets'}</small></div><p>${t.settled?t.pct+' won':'No settled bets yet'}${t.pending?' · '+t.pending+' pending':''}${t.voided?' · '+t.voided+' excluded':''}</p></div>`}
function predictionType(r){const id=r.id.toLowerCase();return id.startsWith('multi')?'multi':id.includes('trifecta')?'trifecta':id.includes('firstfour')?'firstfour':id.includes('exacta')?'exacta':id==='quaddie'?'quaddie':null}
function plainActualRecords(m){return actualRecords(m).map((r,i)=>{const b=m.actualBets[i];return {...r,type:b.type,label:b.source?.label||betNames[b.type]+(b.positions?' · '+({straight:'Straight',boxed:'Boxed',positional:'Position selections',tickets:'Custom combinations'})[b.mode]:'')}})}
function resultCategories(records,prefix='results'){const types=['quaddie','trifecta','firstfour','exacta','multi','daily','treble'];return types.filter(type=>records.some(r=>r.type===type)).map(type=>{const rs=records.filter(r=>r.type===type),t=resultTotals(rs),groups=new Map;for(const r of rs){const key=(r.version||'')+':'+r.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}return `<details class="panel result-category" data-category="${type}"><summary><span>${({quaddie:'Quaddies',trifecta:'Trifectas',firstfour:'First Fours',exacta:'Exactas',multi:'Multis',daily:'Daily Doubles',treble:'Trebles'})[type]}</span><span class="compact muted">${t.settled?t.wins+'/'+t.settled+' won · '+t.pct:t.pending?t.pending+' pending':'No settled bets'}</span></summary>${[...groups.values()].map(group=>{const g=resultTotals(group);return `<div class="result-group"><h3>${escapeHTML(group[0].label)}</h3><p><strong>${g.wins} wins from ${g.settled} settled bets</strong>${g.settled?' · '+g.pct:''}</p>${g.pending||g.voided?`<p class="muted compact">${g.pending} pending · ${g.voided} excluded</p>`:''}</div>`}).join('')}</details>`}).join('')}
function simpleAccuracy(){let races=store.meetings.filter(m=>m.completed).flatMap(m=>assess(m).filter(r=>!excludeScratchingRecommendations||!m.scratchings?.[r.leg]?.length));const n=races.length;return `<details class="panel"><summary>How accurate were the selections?</summary><p class="muted compact">${n} races with a winner entered${excludeScratchingRecommendations?' · races with scratchings excluded':''}.</p>${[['Highest-ranked horse won','top'],['Winner among the four highest-ranked horses','top4'],['Winner in KingMick’s selections','covered']].map(([label,key])=>`<div class="row"><span>${label}</span><strong>${races.filter(r=>r[key]).length} of ${n}</strong></div>`).join('')}<details><summary>What does this mean?</summary><p class="compact muted">These counts check each race separately. For example, “2 of 4” means the highest-ranked horse won two of the four races. Having the winner in your selected horses does not mean a whole Quaddie or multi won.</p></details></details>`}
function allDuplicateGroups(){return store.meetings.flatMap(m=>{if(!m.completed||!m.snapshot)return [];return [...reviewLinks(reviewRows(m),m).links].filter(([,bets])=>bets.length>1).map(([key,bets])=>({m,key,bets}))})}
function stats(){screen='stats';const actual=performanceView==='actual',nav=`<div class="tabs result-tabs"><button data-a="view:actual" class="${actual?'active':''}">My Bet Results</button><button data-a="view:original" class="${!actual?'active':''}">KingMick Predictions</button></div>`;let body;if(actual){const records=store.meetings.flatMap(plainActualRecords),duplicates=allDuplicateGroups();body=`<p class="muted">Results for the bets you recorded as placed.</p>${duplicates.length?`<div class="notice compact">${duplicates.length} recommendation(s) have more than one linked ticket. They remain in the totals until you review them.${button('REVIEW DUPLICATE LINKS','duplicates','secondary')}</div>`:''}${records.length?totalsHTML(records)+'<h2>Results by bet type</h2>'+resultCategories(records):`<div class="panel"><h3>No bets recorded yet</h3><p class="muted">Open a saved meeting and review the bets you placed.</p>${button('OPEN HISTORY','history','secondary')}</div>`}<details class="panel"><summary>What counts as a win?</summary><p class="compact muted">Won and Lost bets count towards the totals. Pending, Void and Didn’t Place do not. Each recorded ticket counts once. Outcomes may come from your entered results or the result you marked manually.</p></details>`}else{const all=store.meetings.flatMap(strategyRecords).filter(r=>!excludeScratchingRecommendations||!r.scratchingAffected).map(r=>({...r,type:predictionType(r)})),currentRules=all.filter(r=>r.version==='v3'),earlier=all.filter(r=>r.version!=='v3'),main=currentRules.length?currentRules:earlier;body=`<p class="muted">How the original recommendations matched your entered race results, whether or not you placed them.</p><label class="simple-toggle"><input type="checkbox" id="scratch-toggle" ${excludeScratchingRecommendations?'checked':''}> Exclude scratching-affected bets</label>${main.length?`${!currentRules.length?'<p class="compact muted">Showing the earlier recommendations saved in your history.</p>':''}${totalsHTML(main)}<h2>Results by bet type</h2>${resultCategories(main)}`:`<div class="panel"><h3>No predictions to show</h3><p class="muted">${excludeScratchingRecommendations?'No recommendations match this filter. Try turning it off.':'Complete a meeting and enter its results to see prediction accuracy here.'}</p>${button('OPEN HISTORY','history','secondary')}</div>`}${currentRules.length&&earlier.length?`<details class="panel"><summary>Earlier recommendations</summary><p class="compact muted">Saved under earlier betting rules, so these results are shown separately.</p>${totalsHTML(earlier)}${resultCategories(earlier,'earlier')}</details>`:''}${simpleAccuracy()}`}show(title('KINGMICK PERFORMANCE','Results')+nav+body+button('HOME','home','ghost'))}
function profileMatches(p,t){if(t.profileId)return t.profileId===p.id;const names=[p.name,...(p.aliases||[])].map(normName).filter(Boolean);return names.includes(normName(t.name))}
function profileMeetings(p){return store.meetings.filter(m=>[...(m.tipsters||[]),...(m.snapshot?.tipsters||[])].some(t=>profileMatches(p,t)))}
function profilesPage(){screen='profiles';const rows=store.profiles.map(p=>{const meetings=profileMeetings(p),picks=store.meetings.filter(m=>m.completed).flatMap(m=>(m.snapshot?.tipsters||m.tipsters||[]).filter(t=>profileMatches(p,t)).flatMap(t=>t.legs.map((leg,i)=>({m,leg,i})))).filter(x=>completedLeg(x.m,x.i));return {p,meetings,picks,wins:picks.filter(x=>sameHorse(x.leg[0],x.m.results[x.i][0])).length,covered:picks.filter(x=>x.leg.some(h=>sameHorse(h,x.m.results[x.i][0]))).length}}).sort((a,b)=>b.picks.length-a.picks.length||a.p.name.localeCompare(b.p.name)),unused=rows.filter(r=>!r.meetings.length);show(title('TIPSTERS','Your Tipsters',`${rows.length} saved · ${unused.length} unused`)+`<p class="muted compact">Only tipsters with no links to any saved meeting can be deleted.</p>${unused.length?button('DELETE ALL '+unused.length+' UNUSED TIPSTERS','deleteunused','secondary'):''}${rows.map(({p,meetings,picks,wins,covered})=>`<div class="panel" data-profile="${escapeHTML(p.id)}"><h3>${escapeHTML(p.name)}</h3>${picks.length?`<div class="row"><span>Best pick won</span><strong>${wins} of ${picks.length} races</strong></div><div class="row"><span>Winner in their four picks</span><strong>${covered} of ${picks.length} races</strong></div>`:'<p class="muted compact">No race results yet.</p>'}${meetings.length?`<p class="muted compact">Used in ${meetings.length} saved meeting(s) · protected from deletion</p>`:button('DELETE UNUSED TIPSTER','deleteprofile:'+p.id,'ghost')}</div>`).join('')||'<div class="panel muted">No saved tipsters yet.</div>'}${button('HOME','home','ghost')}`)}
function deleteProfile(id){const p=store.profiles.find(p=>p.id===id);if(!p)return;if(profileMeetings(p).length)return alert('This tipster is linked to a saved meeting and cannot be deleted.');if(!confirm(`Delete unused tipster “${p.name}”?`))return;store.profiles=store.profiles.filter(p=>p.id!==id);persist();profilesPage()}
function deleteUnusedProfiles(){const unused=store.profiles.filter(p=>!profileMeetings(p).length);if(!unused.length)return profilesPage();if(!confirm(`Delete ${unused.length} unused tipster profile(s)? Profiles linked to saved meetings will be kept.`))return;const ids=new Set(unused.map(p=>p.id));store.profiles=store.profiles.filter(p=>!ids.has(p.id)||profileMeetings(p).length);persist();profilesPage()}
function reviewFinished(row,links){const bets=links.get(row.key)||[];return !bets.length?current.betReview?.[row.key]==='notplaced':bets.length===1&&['hit','miss','void'].includes(assessActual(current,bets[0]).state)}
function reviewBets(){const wasReview=screen==='reviewbets',scroll=wasReview?window.scrollY:0;v42ReviewBets();const rows=reviewRows(),visible=filteredReviewRows(rows),{links}=reviewLinks(rows),finished=visible.filter(r=>reviewFinished(r,links)),todo=visible.length-finished.length;const intro=app.querySelector('.panel');intro.innerHTML=`<h3>${todo} left to review</h3><p class="muted compact">${finished.length} reviewed in this view. Tap an outcome; finished bets move below.</p>`;const unmatched=reviewLinks(rows).unmatched;if(unmatched.length)intro.insertAdjacentHTML('beforeend',`<p class="notice compact">${unmatched.length} existing ticket(s) need linking. Use Link Existing Ticket on their recommendation.</p>`);const bulk=app.querySelector('.bulk-review');bulk.querySelector('h3').textContent='Record several losses';bulk.querySelector('p').textContent='Select the bets you placed, then mark them Lost.';
const reviewed=document.createElement('details');reviewed.id='reviewed-bets';reviewed.className='panel reviewed-section';reviewed.innerHTML=`<summary>Reviewed (${finished.length})</summary>`;const cards=[...app.querySelectorAll('[data-review-row]')];for(const card of cards){const key=card.dataset.reviewRow,row=rows.find(r=>r.key===key),bets=links.get(key)||[];if(bets.length>1){card.innerHTML=`<h3>${escapeHTML(row.label)}${row.leg!==undefined?' · '+legLabel(current,row.leg):''}</h3><p class="notice compact">More than one ticket is linked here. Choose which one to keep.</p>${button('REVIEW DUPLICATE TICKETS','duprow:'+key,'secondary')}`;continue}if(reviewFinished(row,links)){reviewSelected.delete(key);const item=document.createElement('details');item.className='compact-reviewed';const status=bets.length?outcomeLabel(assessActual(current,bets[0]).state):'DIDN’T PLACE';item.innerHTML=`<summary>${row.leg!==undefined?legLabel(current,row.leg)+' · ':''}${escapeHTML(row.label)} <span class="muted">${status}</span></summary>`;item.appendChild(card);reviewed.appendChild(item)}}const optional=[...app.querySelectorAll('.panel')].find(p=>p.querySelector('h3')?.textContent==='Optional Daily Double / Treble');if(finished.length)app.insertBefore(reviewed,optional||null);if(!todo){const message=document.createElement('p');message.className='notice';message.textContent='All done in this view. Your choices are saved.';app.insertBefore(message,bulk.nextSibling)}if(wasReview)window.scrollTo(0,scroll)}
function duplicatesPage(){screen='duplicates';const groups=allDuplicateGroups();show(title('MY BETS','Duplicate ticket links','Review before choosing one ticket to keep.')+groups.map(({m,key,bets})=>`<div class="panel"><h3>${escapeHTML(m.name)}</h3><p>${bets.length} tickets linked to ${escapeHTML(reviewRows(m).find(r=>r.key===key)?.label||key)}</p>${button('COMPARE TICKETS','dupopen:'+encodeURIComponent(m.id)+'|'+encodeURIComponent(key),'secondary')}</div>`).join('')+(!groups.length?'<div class="panel muted">No duplicate recommendation links.</div>':'')+button('BACK TO RESULTS','stats','ghost'))}
function duplicateTickets(key){const row=reviewRows().find(r=>r.key===key),bets=reviewLinks().links.get(key)||[];screen='duplicatecompare';show(title('DUPLICATE TICKETS',row?.label||'Recorded tickets',current.name)+`<p class="muted">Choose the correct ticket to keep. The others will be archived and excluded from results.</p>`+bets.map(b=>`<div class="panel"><h3>${escapeHTML(b.label)}</h3><strong>${outcomeLabel(assessActual(current,b).state)}</strong><p>${escapeHTML(ticketSelections(current,b))}</p>${b.note?`<p class="compact muted">${escapeHTML(b.note)}</p>`:''}${button('KEEP THIS TICKET','dupkeep:'+encodeURIComponent(b.id)+'|'+encodeURIComponent(key))}</div>`).join('')+button('BACK TO REVIEW','reviewbets','ghost'))}
function keepDuplicate(id,key){const bets=reviewLinks().links.get(key)||[],keep=bets.find(b=>b.id===id);if(!keep||bets.length<2)return reviewBets();if(!confirm(`Keep “${keep.label}” and archive ${bets.length-1} other linked ticket(s)? Archived tickets will be excluded from results.`))return;const remove=bets.filter(b=>b.id!==id);current.archivedBets||=[];current.archivedBets.push(...remove.map(b=>({...structuredClone(b),archivedAt:Date.now(),archiveReason:'Duplicate recommendation link'})));const ids=new Set(remove.map(b=>b.id));current.actualBets=current.actualBets.filter(b=>!ids.has(b.id));keep.reviewKey=key;persist();reviewBets()}
function openRecordedRecommendation(key){const bets=reviewLinks().links.get(key)||[];if(!bets.length)return false;if(bets.length>1)duplicateTickets(key);else editActual(bets[0].id);return true}
function fromStrategy(i,id){reviewReturn=false;if(!openRecordedRecommendation(`race:${i}:${id}`))v42FromStrategy(i,id)}
function fromQuaddie(){reviewReturn=false;if(!openRecordedRecommendation('quaddie'))v42FromQuaddie()}
function fromMulti(id){reviewReturn=false;if(!openRecordedRecommendation('multi:'+id))v42FromMulti(id)}
function reviewChange(key){const bets=reviewLinks().links.get(key)||[];if(bets.length>1)return duplicateTickets(key);return v42ReviewChange(key)}
function duplicateSignature(b){try{return ticketSignature(b)}catch{return JSON.stringify([b.type,b.raceIndex,b.mode,b.mode==='boxed'?b.pool?.slice().sort():b.slots?.map(s=>s.slice().sort())])}}
function conflictingTicket(b){const key=explicitReviewKey(b),{links}=reviewLinks();let candidates=key&&links.has(key)?links.get(key):[];let other=candidates.find(t=>t.id!==b.id);if(other)return {other,key};const sig=duplicateSignature(b);other=(current.actualBets||[]).find(t=>t.id!==b.id&&duplicateSignature(t)===sig);return other?{other,key:explicitReviewKey(other)}:null}
function saveActual(){try{const b=captureBetEditor(),conflict=conflictingTicket(b);if(conflict){if(b.id&&conflict.key&&reviewLinks().links.get(conflict.key)?.length>1)return duplicateTickets(conflict.key);alert('This bet is already recorded. Edit the existing ticket instead of adding a duplicate.');return editActual(conflict.other.id)}}catch(e){return alert(e.message)}return v42SaveActual()}
function reviewAttach(key){const id=document.querySelector('#reviewexisting').value,other=(reviewLinks().links.get(key)||[]).find(b=>b.id!==id);if(other){alert('This recommendation already has a recorded ticket. Edit it instead of linking another.');return reviewBets()}return v42ReviewAttach(key)}
function dispatch(a){if(a==='stats'){performanceView='actual';return stats()}if(a==='deleteunused')return deleteUnusedProfiles();if(a.startsWith('deleteprofile:'))return deleteProfile(a.slice(14));if(a==='duplicates')return duplicatesPage();if(a.startsWith('duprow:'))return duplicateTickets(a.slice(7));if(a.startsWith('dupopen:')){const [mid,key]=a.slice(8).split('|').map(decodeURIComponent);current=store.meetings.find(m=>m.id===mid);if(current)return duplicateTickets(key);return}if(a.startsWith('dupkeep:')){const [id,key]=a.slice(8).split('|').map(decodeURIComponent);return keepDuplicate(id,key)}return v42Dispatch(a)}
app.addEventListener('change',e=>{if(e.target.id==='scratch-toggle'){excludeScratchingRecommendations=e.target.checked;stats()}});
